 void startSystemSyncInBackground(){if(syncStarted||systemSynced||!getPackageName().equals(Telephony.Sms.getDefaultSmsPackage(this)))return;syncStarted=true;new Thread(()->{boolean ok=syncSystemMessages();if(isFinishing()||isDestroyed())return;runOnUiThread(()->{if(ok){systemSynced=true;if(list!=null)render();}else syncStarted=false;});},"hashem-sms-sync").start();}
 boolean syncSystemMessages(){if(!getPackageName().equals(Telephony.Sms.getDefaultSmsPackage(this)))return false;android.database.Cursor c=null;android.content.SharedPreferences prefs=getSharedPreferences("sms_sync",MODE_PRIVATE);long lastSync=prefs.getLong("last_successful_sync",0L);String selection=lastSync>0?Telephony.Sms.DATE+">=?":null;String[] args=lastSync>0?new String[]{String.valueOf(Math.max(0,lastSync-120000L))}:null;try{c=getContentResolver().query(Telephony.Sms.CONTENT_URI,new String[]{Telephony.Sms._ID,Telephony.Sms.ADDRESS,Telephony.Sms.BODY,Telephony.Sms.TYPE,Telephony.Sms.DATE,Telephony.Sms.READ},selection,args,Telephony.Sms.DATE+" DESC");if(c==null)return false;while(c.moveToNext())db.importSystemMessage(c.getLong(0),c.getString(1),c.getString(2),c.getInt(3),c.getLong(4),c.getInt(5));prefs.edit().putLong("last_successful_sync",System.currentTimeMillis()).apply();return true;}catch(Exception e){return false;}finally{if(c!=null)c.close();}}
