 void render(){if(list==null)return;list.removeAllViews();if("trash".equals(filter)){trashScreen();return;}if("starred".equals(filter)){starredScreen();return;}if("bulk".equals(filter)){bulkScreen();return;}if("groups".equals(filter)){groupsScreen();return;}if("rules".equals(filter)){forwardRulesScreen();return;}if("scheduled".equals(filter)){scheduledScreen();return;}if("failed".equals(filter)){failedScreen();return;}CursorWrapper c=new CursorWrapper(db.listThreads(filter));String q=search.getText().toString().trim();int n=0;while(c.moveToNext()){String a=c.getString("address"),body=c.getString("body"),st=c.getString("status");String contact=contactName(a);if(!q.isEmpty()&&!a.toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT))&&!body.toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT))&&!contact.toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT)))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(6,8,6,8);LinearLayout avatar=createContactAvatar(a,contact);LinearLayout.LayoutParams avp=new LinearLayout.LayoutParams((int)(getResources().getDisplayMetrics().density*52),(int)(getResources().getDisplayMetrics().density*52));avp.setMargins(0,0,12,0);row.addView(avatar,avp);LinearLayout details=new LinearLayout(this);details.setOrientation(LinearLayout.VERTICAL);details.setGravity(Gravity.CENTER_VERTICAL);details.setLayoutDirection(View.LAYOUT_DIRECTION_LOCALE);TextView a1=tv(contact.isEmpty()?a:contact,16);a1.setTypeface(Typeface.DEFAULT,Typeface.BOLD);a1.setTextColor(Color.rgb(32,31,36));a1.setSingleLine(true);a1.setEllipsize(android.text.TextUtils.TruncateAt.END);TextView b=tv(body,14);b.setTextColor(Color.rgb(100,96,108));b.setSingleLine(true);b.setEllipsize(android.text.TextUtils.TruncateAt.END);a1.setPadding(2,2,2,2);b.setPadding(2,2,2,2);details.addView(a1,new LinearLayout.LayoutParams(-1,-2));details.addView(b,new LinearLayout.LayoutParams(-1,-2));row.addView(details,new LinearLayout.LayoutParams(0,-2,1));LinearLayout meta=new LinearLayout(this);meta.setOrientation(LinearLayout.VERTICAL);meta.setGravity(Gravity.CENTER_HORIZONTAL);TextView status=tv(st,10);status.setTextColor(purple);status.setPadding(3,2,3,2);meta.addView(status);long stamp=0;try{stamp=Long.parseLong(c.getString("ts"));}catch(Exception ignored){}TextView time=tv(stamp>0?new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(stamp)):"",11);time.setTextColor(Color.rgb(120,116,128));time.setPadding(3,2,3,2);meta.addView(time);row.addView(meta);row.setMinimumHeight((int)(getResources().getDisplayMetrics().density*72));row.setOnClickListener(v->{Intent i=new Intent(this,ConversationActivity.class);i.putExtra("address",a);startActivity(i);});row.setOnLongClickListener(v->{PopupMenu menu=new PopupMenu(this,row);boolean archived="archived".equals(filter),blocked="blocked".equals(filter);menu.getMenu().add(archived?"إلغاء الأرشفة":"أرشفة المحادثة");menu.getMenu().add(blocked?"إلغاء الحظر":"حظر الرقم");menu.setOnMenuItemClickListener(item->{String action=item.getTitle().toString();if("أرشفة المحادثة".equals(action)||"إلغاء الأرشفة".equals(action)){db.setConversationFlag(a,"archived","أرشفة المحادثة".equals(action));}else if("حظر الرقم".equals(action)||"إلغاء الحظر".equals(action)){db.setConversationFlag(a,"blocked","حظر الرقم".equals(action));}render();return true;});menu.show();return true;});list.addView(row);View divider=new View(this);divider.setBackgroundColor(Color.rgb(230,225,235));list.addView(divider,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد محادثات في هذا القسم",18));}
 void starredScreen(){list.addView(tv("الرسائل المميزة",22));list.addView(tv("تظهر هنا الرسائل التي وضعت عليها نجمة داخل المحادثات.",14));android.database.Cursor c=db.list("starred");int n=0;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);while(c.moveToNext()){String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),status=c.getString(c.getColumnIndexOrThrow("status"));if(!q.isEmpty()&&!a.toLowerCase(Locale.ROOT).contains(q)&&!body.toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.addView(tv("★  "+contactName(a)+"  ·  "+a,16));row.addView(tv(body,16));row.addView(tv(status,12));row.setOnClickListener(v->{Intent i=new Intent(this,ConversationActivity.class);i.putExtra("address",a);startActivity(i);});list.addView(row);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل مميزة حاليًا",17));}
 void trashScreen(){list.addView(tv("المهملات",22));list.addView(tv("استعد الرسائل المحذوفة أو احذفها نهائيًا.",14));android.database.Cursor c=db.listTrash();int n=0;while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),status=c.getString(c.getColumnIndexOrThrow("status"));if(!search.getText().toString().trim().isEmpty()&&!a.contains(search.getText().toString().trim())&&!body.contains(search.getText().toString().trim()))continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(8,8,8,8);card.addView(tv("من/إلى: "+a,16));card.addView(tv(body,16));card.addView(tv("الحالة السابقة: "+status,13));LinearLayout actions=new LinearLayout(this);Button restore=button("استعادة");restore.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("استعادة الرسالة").setMessage("ستعود الرسالة إلى المحادثة الأصلية.").setNegativeButton("إلغاء",null).setPositiveButton("استعادة",(d,w)->{db.restoreTrashMessage(id);render();}).show());Button remove=button("حذف نهائي");remove.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("حذف نهائي").setMessage("لا يمكن التراجع عن حذف هذه الرسالة نهائيًا.").setNegativeButton("إلغاء",null).setPositiveButton("حذف نهائي",(d,w)->{db.permanentlyDeleteTrashMessage(id);render();}).show());actions.addView(restore,new LinearLayout.LayoutParams(0,-2,1));actions.addView(remove,new LinearLayout.LayoutParams(0,-2,1));card.addView(actions);list.addView(card);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("المهملات فارغة",17));}
 void failedScreen(){list.addView(tv("الرسائل التي تعذّر إرسالها",22));list.addView(tv("يمكنك مراجعة الرسالة ومحاولة إرسالها مرة أخرى.",14));android.database.Cursor c=db.list("failed");int n=0;while(c.moveToNext()){String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),st=c.getString(c.getColumnIndexOrThrow("status"));if(!search.getText().toString().trim().isEmpty()&&!a.contains(search.getText().toString().trim())&&!body.contains(search.getText().toString().trim()))continue;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(8,8,8,8);card.addView(tv("إلى: "+a,17));card.addView(tv(body,16));card.addView(tv("الحالة: "+st,13));Button retry=button("إعادة الإرسال إلى الرقم الأصلي");retry.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("إعادة إرسال الرسالة؟").setMessage("سيتم إرسال الرسالة مرة أخرى إلى "+a).setNegativeButton("إلغاء",null).setPositiveButton("إرسال", (d,w)->send(a,body)).show());card.addView(retry);Button forward=button("توجيه عبر قاعدة مسماة");forward.setOnClickListener(v->forwardFailedWithRule(a,body));card.addView(forward);list.addView(card);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل فاشلة حاليًا",17));}
 void forwardRulesScreen(){list.addView(tv("قواعد توجيه الرسائل الفاشلة",22));list.addView(tv("أنشئ قاعدة باسم واضح ورقم بديل. لا يتم توجيه أي رسالة تلقائيًا؛ اختر القاعدة يدويًا لكل رسالة فاشلة لتجنب إرسال محتوى دون قصد.",14));Button add=button("＋ إضافة قاعدة توجيه");add.setOnClickListener(v->createForwardRuleDialog());list.addView(add);android.database.Cursor c=db.listForwardRules();int n=0;while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));String name=c.getString(c.getColumnIndexOrThrow("name"));String number=c.getString(c.getColumnIndexOrThrow("destination"));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(8,8,8,8);card.addView(tv(name,18));card.addView(tv("رقم التوجيه: "+number,15));Button del=button("حذف القاعدة");del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("حذف قاعدة التوجيه").setMessage("هل تريد حذف قاعدة \""+name+"\"؟").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(d,w)->{db.deleteForwardRule(id);render();}).show());card.addView(del);list.addView(card);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد قواعد توجيه. أضف قاعدة لتظهر هنا.",16));}
 void createForwardRuleDialog(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText name=new EditText(this);name.setHint("اسم القاعدة، مثل رقم بديل للعمل");EditText number=new EditText(this);number.setHint("رقم الهاتف الذي ستُوجّه إليه الرسالة");number.setInputType(3);p.addView(name);p.addView(number);new AlertDialog.Builder(this).setTitle("إضافة قاعدة توجيه").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",(d,w)->{String n=name.getText().toString().trim(),a=number.getText().toString().trim();if(n.isEmpty()||a.isEmpty()){Toast.makeText(this,"أدخل اسم القاعدة ورقم التوجيه",Toast.LENGTH_LONG).show();return;}if(!a.replaceAll("[\\s()\\-]","").matches("\\+?[0-9]{5,20}")){Toast.makeText(this,"رقم التوجيه غير صالح",Toast.LENGTH_LONG).show();return;}long id=db.createForwardRule(n,a);if(id<0)Toast.makeText(this,"تعذر حفظ القاعدة؛ قد يكون الاسم مستخدمًا",Toast.LENGTH_LONG).show();else{Toast.makeText(this,"تم حفظ قاعدة التوجيه",Toast.LENGTH_SHORT).show();render();}}).show();}
 void forwardFailedWithRule(String originalAddress,String body){android.database.Cursor c=db.listForwardRules();ArrayList<Long> ids=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();ArrayList<String> destinations=new ArrayList<>();while(c.moveToNext()){ids.add(c.getLong(c.getColumnIndexOrThrow("id")));labels.add(c.getString(c.getColumnIndexOrThrow("name"))+" — "+c.getString(c.getColumnIndexOrThrow("destination")));destinations.add(c.getString(c.getColumnIndexOrThrow("destination")));}c.close();if(ids.isEmpty()){new AlertDialog.Builder(this).setMessage("لا توجد قواعد توجيه. أضف قاعدة أولًا من تبويب قواعد التوجيه.").setPositiveButton("حسنًا",null).show();return;}new AlertDialog.Builder(this).setTitle("اختر قاعدة التوجيه").setItems(labels.toArray(new String[0]),(dialog,which)->new AlertDialog.Builder(this).setTitle("تأكيد التوجيه").setMessage("ستُرسل نسخة من نص الرسالة الفاشلة إلى "+destinations.get(which)+" عبر القاعدة: "+labels.get(which)+". لن تُرسل إلى المستلم الأصلي بهذه الخطوة.").setNegativeButton("إلغاء",null).setPositiveButton("توجيه الآن",(d,w)->send(destinations.get(which),body)).show()).setNegativeButton("إلغاء",null).show();}
 void composeDialog(){composeDialog("");}void composeDialog(String addr){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText to=new EditText(this);to.setHint("رقم الهاتف");to.setText(addr);EditText body=new EditText(this);body.setHint("اكتب رسالتك");body.setMinLines(4);p.addView(to);p.addView(body);AlertDialog dlg=new AlertDialog.Builder(this).setTitle("رسالة جديدة").setView(p).setPositiveButton("إرسال",(d,w)->send(to.getText().toString(),body.getText().toString())).setNegativeButton("إلغاء",null).setNeutralButton("جدولة",null).create();dlg.show();dlg.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{String a=to.getText().toString().trim(),b=body.getText().toString();if(a.isEmpty()||b.trim().isEmpty()){Toast.makeText(this,"أدخل الرقم ونص الرسالة",Toast.LENGTH_SHORT).show();return;}schedule(a,b);dlg.dismiss();});}
 void send(String a,String b){a=a.trim();if(a.isEmpty()||b.trim().isEmpty()){Toast.makeText(this,"أدخل رقم الهاتف ونص الرسالة",Toast.LENGTH_SHORT).show();return;}long id=db.addMessage(a,b,"out","sending");db.saveOutgoingToSystemProvider(this,id);try{SmsManager sm=SmsManager.getDefault();ArrayList<String> parts=sm.divideMessage(b);ArrayList<PendingIntent> sent=new ArrayList<>(),del=new ArrayList<>();for(int i=0;i<parts.size();i++){Intent si=new Intent(this,SentReceiver.class);si.putExtra("id",id);si.putExtra("partCount",parts.size());si.putExtra("partIndex",i);si.setAction(getPackageName()+".SENT."+id+"."+i);Intent di=new Intent(this,DeliveredReceiver.class);di.putExtra("id",id);di.setAction(getPackageName()+".DELIVERED."+id+"."+i);sent.add(PendingIntent.getBroadcast(this,1000+(int)(id%100000)*10+i,si,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));del.add(PendingIntent.getBroadcast(this,2000+(int)(id%100000)*10+i,di,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}sm.sendMultipartTextMessage(a,null,parts,sent,del);Toast.makeText(this,"بدأت محاولة إرسال الرسالة",Toast.LENGTH_SHORT).show();}catch(Exception e){db.status(id,"failed");db.updateSystemProviderStatus(this,id,false);new AlertDialog.Builder(this).setTitle("تعذّر الإرسال").setMessage(e.getMessage()==null?"تحقق من صلاحية SMS والشبكة والشريحة.":e.getMessage()).setPositiveButton("حسنًا",null).show();}if(!"bulk".equals(filter))render();}
 void schedule(String a,String b){Calendar cal=Calendar.getInstance();cal.add(Calendar.MINUTE,5);DatePickerDialog datePicker=new DatePickerDialog(this,(view,year,month,day)->{cal.set(Calendar.YEAR,year);cal.set(Calendar.MONTH,month);cal.set(Calendar.DAY_OF_MONTH,day);TimePickerDialog timePicker=new TimePickerDialog(this,(timeView,hour,minute)->{cal.set(Calendar.HOUR_OF_DAY,hour);cal.set(Calendar.MINUTE,minute);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);long when=cal.getTimeInMillis();if(when<=System.currentTimeMillis()){Toast.makeText(this,"اختر موعدًا في المستقبل",Toast.LENGTH_LONG).show();return;}confirmSchedule(a,b,when);},cal.get(Calendar.HOUR_OF_DAY),cal.get(Calendar.MINUTE),true);timePicker.setTitle("اختر وقت الإرسال");timePicker.show();},cal.get(Calendar.YEAR),cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH));datePicker.setTitle("اختر تاريخ الإرسال");datePicker.getDatePicker().setMinDate(System.currentTimeMillis());datePicker.show();}
 void confirmSchedule(String a,String b,long when){String whenText=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date(when));new AlertDialog.Builder(this).setTitle("تأكيد جدولة الرسالة").setMessage("سيتم إرسال الرسالة إلى "+a+" في "+whenText+".").setNegativeButton("إلغاء",null).setPositiveButton("تأكيد الجدولة",(d,w)->{long messageId=db.addMessage(a,b,"out","scheduled");db.saveSchedule(messageId,a,b,when);AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);Intent i=new Intent(this,ScheduleReceiver.class);i.putExtra("address",a);i.putExtra("body",b);i.putExtra("id",messageId);i.setAction(getPackageName()+".SCHEDULED."+messageId);PendingIntent pi=PendingIntent.getBroadcast(this,(int)(messageId%100000),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(am!=null){if(Build.VERSION.SDK_INT>=31&&am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);else if(Build.VERSION.SDK_INT>=23)am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,pi);else am.set(AlarmManager.RTC_WAKEUP,when,pi);}Toast.makeText(this,"تمت جدولة الرسالة؛ قد يتأخر التنفيذ إذا لم تسمح إعدادات أندرويد بالمنبه الدقيق",Toast.LENGTH_LONG).show();render();}).show();}
 void scheduledScreen(){list.addView(tv("الرسائل المجدولة",22));list.addView(tv("راجع الرسائل التي تنتظر الإرسال أو ألغِ جدولتها قبل موعدها.",14));android.database.Cursor c=db.listSchedules();int n=0;while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));String a=c.getString(c.getColumnIndexOrThrow("address"));String body=c.getString(c.getColumnIndexOrThrow("body"));long at=c.getLong(c.getColumnIndexOrThrow("at"));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(8,8,8,8);card.addView(tv("إلى: "+a,16));card.addView(tv(body,16));card.addView(tv("الموعد: "+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date(at)),13));Button cancel=button("إلغاء الجدولة");cancel.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("إلغاء الرسالة المجدولة").setMessage("لن تُرسل هذه الرسالة في الموعد المحدد.").setNegativeButton("العودة",null).setPositiveButton("إلغاء الجدولة",(d,w)->{AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);Intent intent=new Intent(this,ScheduleReceiver.class);intent.putExtra("address",a);intent.putExtra("body",body);intent.putExtra("id",id);intent.setAction(getPackageName()+".SCHEDULED."+id);PendingIntent pi=PendingIntent.getBroadcast(this,(int)(id%100000),intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(am!=null)am.cancel(pi);db.deleteSchedule(id);db.status(id,"تم إلغاء الجدولة");render();Toast.makeText(this,"تم إلغاء الجدولة",Toast.LENGTH_SHORT).show();}).show());card.addView(cancel);list.addView(card);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل مجدولة حاليًا.",16));}
 void bulkScreen(){list.addView(tv("الرسائل الجماعية",22));list.addView(tv("اكتب رقمًا في كل سطر، ويمكن إضافة الاسم بعد فاصلة: 777123456, أحمد. استخدم {name} داخل نص الرسالة للتخصيص.",14));Button imp=button("استيراد ملف نصي أو CSV");imp.setOnClickListener(v->importFile());list.addView(imp);Button contacts=button("اختيار من جهات الاتصال · بحث وتحديد الكل");contacts.setOnClickListener(v->pickContactsForBulk());list.addView(contacts);bulkNumbers=new EditText(this);bulkNumbers.setHint("الرقم أو الرقم, الاسم — سطر لكل مستلم");bulkNumbers.setMinLines(5);bulkNumbers.setGravity(Gravity.TOP);list.addView(bulkNumbers);bulkBody=new EditText(this);bulkBody.setHint("نص الرسالة. مثال: مرحبًا {name}");bulkBody.setMinLines(4);bulkBody.setGravity(Gravity.TOP);list.addView(bulkBody);Button send=button("مراجعة ثم إرسال");send.setOnClickListener(v->confirmBulk());list.addView(send);}
 void pickContactsForBulk(){
  ArrayList<String[]> all=new ArrayList<>();
  try{
   android.database.Cursor c=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME+" COLLATE NOCASE ASC");
   if(c!=null){while(c.moveToNext()){String name=c.getString(0),number=c.getString(1);if(number==null)continue;number=number.trim();if(number.isEmpty())continue;all.add(new String[]{name==null?"":name,number});}c.close();}
  }catch(Exception e){Toast.makeText(this,"تعذّر قراءة جهات الاتصال. تحقق من الإذن.",Toast.LENGTH_LONG).show();return;}
  if(all.isEmpty()){Toast.makeText(this,"لا توجد أرقام في جهات الاتصال.",Toast.LENGTH_LONG).show();return;}
  LinkedHashMap<String,String[]> selected=new LinkedHashMap<>();
  LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(4,4,4,4);
  EditText query=new EditText(this);query.setSingleLine(true);query.setHint("ابحث باسم أو جزء من الرقم");panel.addView(query,new LinearLayout.LayoutParams(-1,-2));
  TextView count=tv("المحدد: 0",14);panel.addView(count);
  LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);
  Button selectAll=button("تحديد كل النتائج");Button clear=button("إلغاء التحديد");
  actions.addView(selectAll,new LinearLayout.LayoutParams(0,-2,1));actions.addView(clear,new LinearLayout.LayoutParams(0,-2,1));panel.addView(actions);
  LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.addView(rows);int pickerHeight=(int)(getResources().getDisplayMetrics().density*360);panel.addView(scroll,new LinearLayout.LayoutParams(-1,pickerHeight));
  final String[] currentQuery={""};
  Runnable refresh=()->{
   rows.removeAllViews();currentQuery[0]=query.getText().toString().trim().toLowerCase(Locale.ROOT);int shown=0;
   for(String[] person:all){String name=person[0],number=person[1];if(!currentQuery[0].isEmpty()&&!name.toLowerCase(Locale.ROOT).contains(currentQuery[0])&&!number.toLowerCase(Locale.ROOT).contains(currentQuery[0]))continue;
    String key=number.replaceAll("[\\s()\\-]","");CheckBox cb=new CheckBox(this);cb.setText((name.isEmpty()?number:name+"  ·  "+number));cb.setTextSize(14);cb.setPadding(8,5,8,5);cb.setChecked(selected.containsKey(key));cb.setOnCheckedChangeListener((v,checked)->{if(checked)selected.put(key,new String[]{name,key});else selected.remove(key);count.setText("المحدد: "+selected.size());});rows.addView(cb);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));rows.addView(line,new LinearLayout.LayoutParams(-1,1));shown++;
   }
   if(shown==0)rows.addView(tv("لا توجد نتائج مطابقة",15));count.setText("المحدد: "+selected.size()+" · النتائج الظاهرة: "+shown);
  };
  query.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){refresh.run();}public void afterTextChanged(android.text.Editable e){}});
  selectAll.setOnClickListener(v->{String q=currentQuery[0];for(String[] person:all){String name=person[0],number=person[1];if(!q.isEmpty()&&!name.toLowerCase(Locale.ROOT).contains(q)&&!number.toLowerCase(Locale.ROOT).contains(q))continue;String key=number.replaceAll("[\\s()\\-]","");selected.put(key,new String[]{name,key});}refresh.run();});
  clear.setOnClickListener(v->{selected.clear();refresh.run();});
  refresh.run();
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("اختيار المستلمين").setView(panel).setNegativeButton("إلغاء",null).setPositiveButton("إضافة المحددين",null).create();
  dialog.setOnShowListener(v->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(btn->{if(selected.isEmpty()){Toast.makeText(this,"حدد مستلمًا واحدًا على الأقل",Toast.LENGTH_SHORT).show();return;}StringBuilder text=new StringBuilder(bulkNumbers==null?"":bulkNumbers.getText().toString().trim());for(String[] person:selected.values()){String number=person[1];if(bulkContainsNumber(text.toString(),number))continue;if(text.length()>0)text.append('\n');text.append(number);if(!person[0].trim().isEmpty())text.append(", ").append(person[0].trim());}if(bulkNumbers!=null)bulkNumbers.setText(text.toString());Toast.makeText(this,"أُضيف "+selected.size()+" جهة محددة إلى القائمة؛ راجع التكرار قبل الإرسال.",Toast.LENGTH_LONG).show();dialog.dismiss();});});
  dialog.show();
 }
 boolean bulkContainsNumber(String current,String number){String target=number.replaceAll("[\\s()\\-]","");for(String line:current.split("\\r?\\n")){String first=line.trim().split(",",2)[0].replaceAll("[\\s()\\-]","");if(first.equals(target))return true;}return false;}
 void confirmBulk(){String raw=bulkNumbers.getText().toString().trim(),body=bulkBody.getText().toString().trim();if(raw.isEmpty()||body.isEmpty()){Toast.makeText(this,"أدخل المستلمين ونص الرسالة أولًا",Toast.LENGTH_SHORT).show();return;}ArrayList<String[]> recipients=new ArrayList<>();HashSet<String> seenNumbers=new HashSet<>();int invalid=0;boolean firstLine=true;for(String line:raw.split("\\r?\\n")){String[] p=line.trim().split(",",2);String number=p[0].trim();if(firstLine&&(number.toLowerCase(Locale.ROOT).contains("phone")||number.toLowerCase(Locale.ROOT).contains("number")||number.contains("رقم"))){firstLine=false;continue;}firstLine=false;if(number.isEmpty())continue;number=number.replaceAll("[\\s()\\-]","");if(!number.matches("\\+?[0-9]{5,20}")){invalid++;continue;}String name=p.length>1?p[1].trim():"";if(seenNumbers.add(number))recipients.add(new String[]{number,name});}if(recipients.isEmpty()){Toast.makeText(this,"لم يتم العثور على أرقام صالحة؛ استخدم رقمًا واحدًا في كل سطر.",Toast.LENGTH_LONG).show();return;}final int invalidCount=invalid;new AlertDialog.Builder(this).setTitle("تأكيد الرسائل الجماعية").setMessage("سيتم إرسال "+recipients.size()+" رسالة نصية"+(invalidCount>0?"، وسيتم تجاهل "+invalidCount+" سطر غير صالح":"")+". قد تُحتسب رسوم من شركة الاتصالات. أرسل فقط لمن وافقوا على تلقي الرسائل.").setNegativeButton("مراجعة",null).setPositiveButton("إرسال", (d,w)->{for(String[] r:recipients){String personalized=body.replace("{name}",r[1]);send(r[0],personalized);}Toast.makeText(this,"تمت معالجة قائمة الإرسال؛ راجع حالات الرسائل لكل مستلم.",Toast.LENGTH_LONG).show();}).show();}
 void groupsScreen(){list.addView(tv("مجموعات المستلمين",22));list.addView(tv("احفظ أسماء المجموعات وأرقام أعضائها، ثم حمّل المجموعة إلى شاشة الرسائل الجماعية.",14));Button add=button("＋ إنشاء مجموعة");add.setOnClickListener(v->createGroupDialog());list.addView(add);android.database.Cursor c=db.listGroups();int n=0;while(c.moveToNext()){long gid=c.getLong(c.getColumnIndexOrThrow("id"));String name=c.getString(c.getColumnIndexOrThrow("name"));android.database.Cursor members=db.groupMembers(gid);int count=members.getCount();members.close();LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(8,8,8,8);card.addView(tv(name,18));card.addView(tv(count+" مستلم",13));Button use=button("استخدام في الرسائل الجماعية");use.setOnClickListener(v->{android.database.Cursor m=db.groupMembers(gid);StringBuilder numbers=new StringBuilder();while(m.moveToNext()){if(numbers.length()>0)numbers.append('\n');numbers.append(m.getString(m.getColumnIndexOrThrow("address")));String person=m.getString(m.getColumnIndexOrThrow("name"));if(person!=null&&!person.trim().isEmpty())numbers.append(", ").append(person);}m.close();filter="bulk";render();bulkNumbers.setText(numbers.toString());});card.addView(use);Button addMembers=button("إضافة مستلمين");addMembers.setOnClickListener(v->addGroupMembersDialog(gid));card.addView(addMembers);Button delete=button("حذف المجموعة");delete.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("حذف المجموعة").setMessage("سيتم حذف المجموعة وأعضائها المحفوظين، ولن تُحذف الرسائل السابقة.").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(dlg,which)->{db.deleteGroup(gid);render();}).show());card.addView(delete);list.addView(card);View line=new View(this);line.setBackgroundColor(Color.rgb(230,225,235));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لم تنشئ أي مجموعة بعد.",16));}
 void createGroupDialog(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText name=new EditText(this);name.setHint("اسم المجموعة، مثل العائلة أو العمل");EditText members=new EditText(this);members.setHint("رقم الهاتف, الاسم — مستلم في كل سطر");members.setMinLines(5);members.setGravity(Gravity.TOP);p.addView(name);p.addView(members);new AlertDialog.Builder(this).setTitle("إنشاء مجموعة").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("حفظ", (d,w)->{String groupName=name.getText().toString().trim(),raw=members.getText().toString().trim();if(groupName.isEmpty()||raw.isEmpty()){Toast.makeText(this,"أدخل اسم المجموعة ومستلمًا واحدًا على الأقل",Toast.LENGTH_LONG).show();return;}long gid=db.createGroup(groupName);if(gid<0){Toast.makeText(this,"تعذر حفظ المجموعة؛ قد يكون الاسم مستخدمًا من قبل",Toast.LENGTH_LONG).show();return;}int added=0;for(String line:raw.split("\\r?\\n")){String[] part=line.trim().split(",",2);String number=part[0].trim();if(number.isEmpty())continue;db.addGroupMember(gid,number,part.length>1?part[1]:"");added++;}Toast.makeText(this,"تم حفظ المجموعة: "+added+" مستلم",Toast.LENGTH_LONG).show();render();}).show();}
 void addGroupMembersDialog(long gid){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText members=new EditText(this);members.setHint("رقم الهاتف, الاسم — مستلم في كل سطر");members.setMinLines(5);members.setGravity(Gravity.TOP);p.addView(members);new AlertDialog.Builder(this).setTitle("إضافة مستلمين للمجموعة").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",(dlg,which)->{int added=0,invalid=0;for(String line:members.getText().toString().split("\\r?\\n")){String[] part=line.trim().split(",",2);String number=part[0].trim().replaceAll("[\\s()\\-]","");if(number.isEmpty())continue;if(!number.matches("\\+?[0-9]{5,20}")){invalid++;continue;}db.addGroupMember(gid,number,part.length>1?part[1]:"");added++;}String message="تم حفظ "+added+" مستلم";if(invalid>0)message+="؛ تم تجاهل "+invalid+" رقم غير صالح";Toast.makeText(this,message,Toast.LENGTH_LONG).show();render();}).show();}void importFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,44);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==44&&c==RESULT_OK&&d!=null){try{InputStream in=getContentResolver().openInputStream(d.getData());BufferedReader br=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String line;while((line=br.readLine())!=null)s.append(line).append('\n');br.close();if(bulkNumbers!=null)bulkNumbers.setText(s.toString());Toast.makeText(this,"تم تحميل محتوى الملف إلى قائمة المستلمين؛ راجعه قبل الإرسال.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"تعذّر قراءة الملف: "+e.getMessage(),Toast.LENGTH_LONG).show();}}}

 LinearLayout createContactAvatar(String number,String name){int size=(int)(getResources().getDisplayMetrics().density*52);LinearLayout holder=new LinearLayout(this);holder.setGravity(Gravity.CENTER);holder.setBackground(rounded(Color.rgb(232,222,248),0,size/2));holder.setClipToOutline(true);Uri photo; synchronized(contactPhotoCache){photo=contactPhotoCache.get(number);}if(photo!=null){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);try{image.setImageURI(photo);}catch(Exception ignored){}if(image.getDrawable()!=null){holder.addView(image,new LinearLayout.LayoutParams(-1,-1));return holder;}}TextView fallback=new TextView(this);fallback.setGravity(Gravity.CENTER);fallback.setText(name==null||name.trim().isEmpty()?number:name.trim());fallback.setTextSize(name!=null&&name.length()>9?7:9);fallback.setTypeface(Typeface.DEFAULT,Typeface.BOLD);fallback.setTextColor(Color.rgb(56,30,114));fallback.setMaxLines(3);fallback.setEllipsize(android.text.TextUtils.TruncateAt.END);fallback.setPadding(2,2,2,2);holder.addView(fallback,new LinearLayout.LayoutParams(-1,-1));return holder;}
 String contactName(String number){synchronized(contactCache){if(contactCache.containsKey(number))return contactCache.get(number);}synchronized(contactLookupPending){if(contactLookupPending.add(number)){contactExecutor.execute(()->{String found="";Uri photo=null;android.database.Cursor c=null;try{Uri uri=Uri.withAppendedPath(ContactsContract.PhoneLookup.CONTENT_FILTER_URI,Uri.encode(number));c=getContentResolver().query(uri,new String[]{ContactsContract.PhoneLookup.DISPLAY_NAME,ContactsContract.PhoneLookup.PHOTO_THUMBNAIL_URI},null,null,null);if(c!=null&&c.moveToFirst()){found=c.getString(0);String p=c.getString(1);if(p!=null&&!p.trim().isEmpty())photo=Uri.parse(p);}}catch(Exception ignored){}finally{if(c!=null)c.close();}synchronized(contactCache){contactCache.put(number,found==null?"":found);}if(photo!=null)synchronized(contactPhotoCache){contactPhotoCache.put(number,photo);}synchronized(contactLookupPending){contactLookupPending.remove(number);}if(!isFinishing()&&!isDestroyed())runOnUiThread(()->{if(list!=null)render();});});}}return "";}
 void requestPermissionsIfNeeded(){if(Build.VERSION.SDK_INT>=23){ArrayList<String> needed=new ArrayList<>();String[] base={"android.permission.SEND_SMS","android.permission.RECEIVE_SMS","android.permission.READ_SMS","android.permission.READ_CONTACTS"};for(String p:base)if(checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)needed.add(p);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)needed.add("android.permission.POST_NOTIFICATIONS");if(!needed.isEmpty())requestPermissions(needed.toArray(new String[0]),5);}}
 void requestDefault(){if(Build.VERSION.SDK_INT>=29){RoleManager rm=(RoleManager)getSystemService(ROLE_SERVICE);if(rm!=null&&rm.isRoleAvailable(RoleManager.ROLE_SMS)&&!rm.isRoleHeld(RoleManager.ROLE_SMS))startActivityForResult(rm.createRequestRoleIntent(RoleManager.ROLE_SMS),99);}else{Intent i=new Intent(Telephony.Sms.Intents.ACTION_CHANGE_DEFAULT);i.putExtra(Telephony.Sms.Intents.EXTRA_PACKAGE_NAME,getPackageName());startActivity(i);}}
 static class CursorWrapper{android.database.Cursor c;CursorWrapper(android.database.Cursor x){c=x;}boolean moveToNext(){return c.moveToNext();}String getString(String col){return c.getString(c.getColumnIndexOrThrow(col));}void close(){c.close();}}
